class Solution { static constexpr int MOD=1000000007;string digits;int minSum,maxSum;vector<vector<int>> memo;int dfs(int pos,int sum,bool tight){if(sum>maxSum)return 0;if(pos==(int)digits.size())return sum>=minSum;if(!tight&&memo[pos][sum]!=-1)return memo[pos][sum];int limit=tight?digits[pos]-'0':9;long long ways=0;for(int digit=0;digit<=limit;++digit)ways=(ways+dfs(pos+1,sum+digit,tight&&digit==limit))%MOD;int answer=ways;if(!tight)memo[pos][sum]=answer;return answer;}int countUpTo(const string& bound){digits=bound;memo.assign(digits.size(),vector<int>(maxSum+1,-1));return dfs(0,0,true);}bool valid(const string& value){int sum=0;for(char ch:value)sum+=ch-'0';return sum>=minSum&&sum<=maxSum;}public:int count(string num1,string num2,int min_sum,int max_sum){minSum=min_sum;maxSum=max_sum;long long answer=(long long)countUpTo(num2)-countUpTo(num1)+(valid(num1)?1:0);answer%=MOD;if(answer<0)answer+=MOD;return answer;} };
